string conta = "";

foreach (int n in numeros)
{
    if (conta != "")
    {
        conta = conta + " + ";
    }

    conta = conta + n;
}

return conta;   //  "7 + 9 + 8"

int maior = 0;

foreach (int n in numeros)
{
    if (n > maior)
    {
        maior = n;
    }
}

return maior;

